  "/api/tools/ocr/jobs/ocr1/sync-lead",
  "/api/lead-finder/providers",
  "/api/lead-finder/search",
  "/api/lead-finder/source-config",
  "/api/ai-site-builder/capabilities",
  "/api/ai-site-builder/models",
